@page "/settings"
@rendermode InteractiveServer
@using sv_b2da2e52614640a28d38aa6ccc3aa4f9.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="nav flex-column">
            @foreach (var section in _sections)
            {
                <li class="nav-item">
                    <button class="nav-link @(ActiveSection == section.Key ? "active" : "")"
                            @onclick="() => ActiveSection = section.Key">
                        <span class="section-icon">@section.Icon</span>
                        @section.Label
                    </button>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_toastMessage))
            {
                <div class="alert @_toastClass alert-dismissible fade show" role="alert">
                    @_toastMessage
                    <button type="button" class="btn-close" @onclick="DismissToast"></button>
                </div>
            }

            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfile()
                    break;
                case "notifications":
                    @RenderNotifications()
                    break;
                case "security":
                    @RenderSecurity()
                    break;
                case "appearance":
                    @RenderAppearance()
                    break;
            }
        }
    </div>
</div>

@* ── Profile Section ── *@

@{
    RenderFragment RenderProfile() =>
        @<div class="settings-section">
            <h3>Profile</h3>
            <p class="text-muted">Manage your personal information</p>
            <hr />

            <div class="avatar-area mb-4">
                <img src="@_editProfile!.AvatarUrl" alt="Avatar" class="avatar-preview" />
                <span class="text-muted small ms-3">@_editProfile.AvatarUrl</span>
            </div>

            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="_editProfile.DisplayName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="_editProfile.Email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="_editProfile.Bio"></textarea>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">
                    Discard Changes
                </button>
            </div>
        </div>;
}

@* ── Notifications Section ── *@

@{
    RenderFragment RenderNotifications() =>
        @<div class="settings-section">
            <h3>Notifications</h3>
            <p class="text-muted">Control how you receive notifications</p>
            <hr />

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif"
                       checked="@_editNotifications!.EmailNotifications"
                       @onchange="e => _editNotifications.EmailNotifications = (bool)e.Value!" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif"
                       checked="@_editNotifications.PushNotifications"
                       @onchange="e => _editNotifications.PushNotifications = (bool)e.Value!" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest"
                       checked="@_editNotifications.WeeklyDigest"
                       @onchange="e => _editNotifications.WeeklyDigest = (bool)e.Value!" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>

            <h5 class="mt-4">Muted Channels</h5>
            <div class="channel-list mb-3">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _editNotifications.MutedChannels.Contains(channel);
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="ch-@channel"
                               checked="@isMuted"
                               @onchange="e => ToggleMutedChannel(channel, (bool)e.Value!)" />
                        <label class="form-check-label" for="ch-@channel">@channel</label>
                    </div>
                }
            </div>

            <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Preferences
            </button>
        </div>;
}

@* ── Security Section ── *@

@{
    RenderFragment RenderSecurity() =>
        @<div class="settings-section">
            <h3>Security</h3>
            <p class="text-muted">Manage your account security</p>
            <hr />

            @* Change Password Panel *@
            <div class="card mb-4">
                <div class="card-header d-flex justify-content-between align-items-center"
                     style="cursor:pointer" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <strong>Change Password</strong>
                    <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
                </div>
                @if (_passwordPanelOpen)
                {
                    <div class="card-body">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <div class="text-danger mb-2">@_passwordError</div>
                        }
                        <button class="btn btn-warning" @onclick="UpdatePassword" disabled="@_saving">
                            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            @* Two-Factor Authentication *@
            <div class="d-flex align-items-center mb-4 gap-3">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@_twoFactorEnabled" disabled />
                    <label class="form-check-label" for="twoFactor">Two-Factor Authentication</label>
                </div>
                @if (_twoFactorEnabled)
                {
                    <span class="badge bg-success">Enabled</span>
                }
                else
                {
                    <span class="badge bg-secondary">Disabled</span>
                }
            </div>

            @if (_lastPasswordChange.HasValue)
            {
                <p class="text-muted small">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            @* Active Sessions *@
            <h5 class="mt-4">Active Sessions</h5>
            <div class="table-responsive">
                <table class="table table-striped">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (_sessions is not null)
                        {
                            @foreach (var session in _sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _sessions.First().Id)
                                        {
                                            <button class="btn btn-sm btn-outline-danger"
                                                    @onclick="() => PromptRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="badge bg-info">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            @* Revoke Confirmation Dialog *@
            @if (_sessionToRevoke is not null)
            {
                <div class="modal-backdrop show"></div>
                <div class="modal d-block" tabindex="-1">
                    <div class="modal-dialog modal-dialog-centered">
                        <div class="modal-content">
                            <div class="modal-header">
                                <h5 class="modal-title">Revoke Session</h5>
                                <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                            </div>
                            <div class="modal-body">
                                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                            </div>
                            <div class="modal-footer">
                                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                <button class="btn btn-danger" @onclick="ConfirmRevoke" disabled="@_saving">
                                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                                    Revoke
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            }
        </div>;
}

@* ── Appearance Section ── *@

@{
    RenderFragment RenderAppearance() =>
        @<div class="settings-section">
            <h3>Appearance</h3>
            <p class="text-muted">Customize how the application looks</p>
            <hr />

            <h5>Theme</h5>
            <div class="d-flex gap-3 mb-4">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                               value="@theme"
                               checked="@(_editAppearance!.Theme == theme)"
                               @onchange="() => _editAppearance.Theme = theme" />
                        <label class="form-check-label" for="theme-@theme">@theme</label>
                    </div>
                }
            </div>

            <h5>Font Size</h5>
            <div class="d-flex gap-3 mb-4">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                               value="@size"
                               checked="@(_editAppearance.FontSize == size)"
                               @onchange="() => _editAppearance.FontSize = size" />
                        <label class="form-check-label" for="fs-@size">@size</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h5>Language</h5>
                <select class="form-select w-auto" @bind="_editAppearance.Language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="form-check form-switch mb-4">
                <input class="form-check-input" type="checkbox" id="compactMode"
                       checked="@_editAppearance.CompactMode"
                       @onchange="e => _editAppearance.CompactMode = (bool)e.Value!" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>

            @* Live Preview *@
            <h5>Preview</h5>
            <div class="preview-area @GetPreviewClasses()">
                <div class="preview-header">
                    <strong>Dashboard</strong>
                </div>
                <div class="preview-body">
                    <p>This is a preview of your selected appearance settings.</p>
                    <button class="btn btn-sm @(GetPreviewTheme() == "dark" ? "btn-light" : "btn-primary")">
                        Sample Button
                    </button>
                </div>
            </div>

            <button class="btn btn-primary mt-3" @onclick="SaveAppearance" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>
        </div>;
}

@code {
    private record SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨"),
    ];

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;
    private bool _saving;
    private string? _toastMessage;
    private string _toastClass = "alert-success";

    // Profile state
    private ProfileEdit? _editProfile;
    private UserProfile? _savedProfile;

    // Notification state
    private NotificationEdit? _editNotifications;
    private readonly string[] _allChannels = ["announcements", "marketing", "social", "updates", "general"];

    // Security state
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession>? _sessions;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private AppearanceEdit? _editAppearance;
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Portuguese"];

    // Mutable edit models
    private class ProfileEdit
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }

    private class NotificationEdit
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = [];
    }

    private class AppearanceEdit
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "English";
        public bool CompactMode { get; set; }
    }

    protected override async Task OnInitializedAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _savedProfile = profileTask.Result;
        _editProfile = ToProfileEdit(_savedProfile);

        var notifPrefs = notifTask.Result;
        _editNotifications = new NotificationEdit
        {
            EmailNotifications = notifPrefs.EmailNotifications,
            PushNotifications = notifPrefs.PushNotifications,
            WeeklyDigest = notifPrefs.WeeklyDigest,
            MutedChannels = new List<string>(notifPrefs.MutedChannels),
        };

        var security = securityTask.Result;
        _twoFactorEnabled = security.TwoFactorEnabled;
        _lastPasswordChange = security.LastPasswordChange;
        _sessions = new List<ActiveSession>(security.Sessions);

        var appearance = appearanceTask.Result;
        _editAppearance = new AppearanceEdit
        {
            Theme = appearance.Theme,
            FontSize = appearance.FontSize,
            Language = appearance.Language,
            CompactMode = appearance.CompactMode,
        };

        _loading = false;
    }

    // ── Profile ──

    private static ProfileEdit ToProfileEdit(UserProfile p) => new()
    {
        DisplayName = p.DisplayName,
        Email = p.Email,
        AvatarUrl = p.AvatarUrl,
        Bio = p.Bio,
    };

    private async Task SaveProfile()
    {
        _saving = true;
        var profile = new UserProfile(
            _editProfile!.DisplayName, _editProfile.Email,
            _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _saving = false;
        ShowToast("Profile saved successfully.", "alert-success");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
            _editProfile = ToProfileEdit(_savedProfile);
    }

    // ── Notifications ──

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_editNotifications!.MutedChannels.Contains(channel))
            _editNotifications.MutedChannels.Add(channel);
        else if (!muted)
            _editNotifications!.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _saving = true;
        var prefs = new NotificationPrefs(
            _editNotifications!.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            new List<string>(_editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        ShowToast("Notification preferences saved.", "alert-success");
    }

    // ── Security ──

    private async Task UpdatePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "All password fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        _saving = false;
        ShowToast("Password updated successfully.", "alert-success");
    }

    private void PromptRevokeSession(ActiveSession session)
        => _sessionToRevoke = session;

    private void CancelRevoke()
        => _sessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;
        _saving = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions!.RemoveAll(s => s.Id == _sessionToRevoke.Id);
        _sessionToRevoke = null;
        _saving = false;
        ShowToast("Session revoked.", "alert-success");
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    // ── Appearance ──

    private string GetPreviewTheme()
        => _editAppearance!.Theme == "System" ? "light" : _editAppearance.Theme.ToLowerInvariant();

    private string GetPreviewClasses()
    {
        var theme = GetPreviewTheme();
        var size = _editAppearance!.FontSize.ToLowerInvariant();
        var compact = _editAppearance.CompactMode ? "compact" : "";
        return $"preview-{theme} preview-font-{size} {compact}".Trim();
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        var settings = new AppearanceSettings(
            _editAppearance!.Theme, _editAppearance.FontSize,
            _editAppearance.Language, _editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        ShowToast("Appearance settings saved.", "alert-success");
    }

    // ── Toast ──

    private void ShowToast(string message, string cssClass)
    {
        _toastMessage = message;
        _toastClass = cssClass;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        _toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast() => _toastMessage = null;
}

